import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import WalletModal from '../pages/WalletPage'; // Correctly import the default export WalletModal component

const Sidebar = () => {
  const location = useLocation();
  const { user, logout } = useAuth();
  const [showWalletModal, setShowWalletModal] = useState(false);

  const isActive = (path) => {
    return location.pathname === path;
  };

  const navItems = [
    { path: '/coinflip', label: 'Coinflip' },
    { path: '/blackjack', label: 'Blackjack' },
    { path: '/leaderboard', label: 'Leaderboard' },
    { path: '/stats', label: 'Stats' },
    { path: '/provably-fair', label: 'Provably Fair' },
    { path: '/profile', label: 'Profile' }
  ];

  return (
    <div className="sidebar">
      <div className="sidebar-header">
        <div className="logo">
          <h1 className="logo-text">AMPcoin</h1>
        </div>
      </div>

      <nav className="sidebar-nav">
        <div className="nav-section">
          <h3>Games</h3>
          {navItems.slice(0, 2).map((item) => (
            <Link
              key={item.path}
              to={item.path}
              className={`nav-link ${isActive(item.path) ? 'active' : ''}`}
            >
              {item.label}
            </Link>
          ))}
        </div>

        <div className="nav-section">
          <h3>Other</h3>
          {navItems.slice(2, 5).map((item) => (
            <Link
              key={item.path}
              to={item.path}
              className={`nav-link ${isActive(item.path) ? 'active' : ''}`}
            >
              {item.label}
            </Link>
          ))}

          <Link
            key="/profile"
            to="/profile"
            className={`nav-link ${isActive('/profile') ? 'active' : ''}`}
          >
            Profile
          </Link>
        </div>

        {user?.isAdmin && (
          <div className="nav-section">
            <h3>Admin</h3>
            <Link
              to="/admin"
              className={`nav-link ${isActive('/admin') ? 'active' : ''}`}
            >
              Admin Panel
            </Link>
          </div>
        )}
      </nav>

      <div className="sidebar-footer">
        <div className="user-info">
          <img 
            src={user?.avatar || '/default-avatar.png'} 
            alt="Avatar" 
            className="user-avatar"
            onError={(e) => {
              e.target.src = '/default-avatar.png';
            }}
          />
          <div className="user-details">
            <span className="username">{user?.displayName}</span>
            <span className="balance">{user?.balance?.toLocaleString()} AMP</span>
          </div>
        </div>

        <button className="logout-btn" onClick={logout}>
          Logout
        </button>
      </div>

      {/* Wallet Modal */}
      {showWalletModal && (
        <div className="modal-overlay" onClick={() => setShowWalletModal(false)}>
          <div className="wallet-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Wallet</h2>
              <button className="close-modal" onClick={() => setShowWalletModal(false)}>×</button>
            </div>
            <WalletModal onClose={() => setShowWalletModal(false)} />
          </div>
        </div>
      )}
    </div>
  );
};

export default Sidebar;
